# MTG correspondence model: iStar actors/tasks to BPMN lanes/nodes.
actor Initiator   -> pool MeetingOrganization lane Initiator
actor Organizer   -> pool MeetingOrganization lane Organizer
actor Secretary   -> pool MeetingOrganization lane Secretary
actor Participant -> pool MeetingOrganization lane Participant

map DecideDetails        -> node decideMeetingDetails
map CollectFromCalendar  -> node checkCalendar
map SecretaryRequested   -> node requestSecretaryCall
map ChooseMeetingTime    -> node chooseTimeAndDate
map NotifyParticipant    -> node announceMeeting
map CollectByPhone       -> node collectConstraintsByPhone
map AttendMeeting        -> node participate
